@gql_node_type(
    BackendAIGQLMeta(
        added_version=NEXT_RELEASE_VERSION,
        description=(
            "One write of an auto-generated file's content and permission. Sessions get the "
            "latest revision."
        ),
    ),
    name="AutoGeneratedFileRevision",
)
class AutoGeneratedFileRevisionGQL(PydanticNodeMixin[AutoGeneratedFileRevisionNodeDTO]):
    id: NodeID[str] = gql_field(description="Relay-style global node identifier.")
    field_id: UUID = gql_field(description="ID of the revision.")
    auto_generated_file_id: UUID = gql_field(description="ID of the file.")
    revision_number: int = gql_field(description="Number of the revision, counted from 1 per file.")
    data: str = gql_field(description="Content of the file at this revision.")
    permission: AutoGeneratedFilePermission = gql_field(
        description="Unix file permission in octal, at this revision."
    )
    creator_id: UUID | None = gql_field(
        description="ID of the user who wrote the revision. Null once that user is purged."
    )
    created_at: datetime = gql_field(description="Creation timestamp.")

    @classmethod
    @override
    async def resolve_nodes(
        cls,
        *,
        info: Info[StrawberryGQLContext, Any],
        node_ids: Iterable[str],
        required: bool = False,
    ) -> Iterable[Self]:
        results = await info.context.data_loaders.auto_generated_file_revision_loader.load_many([
            AutoGeneratedFileRevisionID(UUID(node_id)) for node_id in node_ids
        ])
        return cast(list[Self], results)


