@gql_node_type(
    BackendAIGQLMeta(
        added_version=NEXT_RELEASE_VERSION,
        description=(
            "A file written into every session of a domain, a project or a user. Only the "
            "default of a path is written."
        ),
    ),
    name="AutoGeneratedFile",
)
class AutoGeneratedFileGQL(PydanticNodeMixin[AutoGeneratedFileNodeDTO]):
    id: NodeID[str] = gql_field(description="Relay-style global node identifier.")
    entity_id: UUID = gql_field(description="ID of the auto-generated file.")
    scope_type: AutoGeneratedFileScopeTypeGQL = gql_field(
        description="Kind of the scope the file belongs to."
    )
    scope_id: UUID = gql_field(description="ID of the domain, project or user.")
    path: str = gql_field(description="Path the file is written to in a session.")
    is_default: bool = gql_field(description="Whether the file is the default of its path.")
    created_at: datetime = gql_field(description="Creation timestamp.")
    updated_at: datetime = gql_field(description="Last update timestamp.")

    @gql_resolver(description="Revisions of the file's content. The latest is the current one.")
    async def revisions(
        self,
        info: Info[StrawberryGQLContext],
        filter: AutoGeneratedFileRevisionFilterGQL | None = None,
        order_by: list[AutoGeneratedFileRevisionOrderByGQL] | None = None,
        before: str | None = None,
        after: str | None = None,
        first: int | None = None,
        last: int | None = None,
        limit: int | None = None,
        offset: int | None = None,
    ) -> AutoGeneratedFileRevisionConnectionGQL | None:
        payload = await info.context.adapters.auto_generated_file.search_revisions(
            SearchAutoGeneratedFileRevisionsInput(
                auto_generated_file_id=AutoGeneratedFileID(self.entity_id),
                filter=filter.to_pydantic() if filter else None,
                order=[o.to_pydantic() for o in order_by] if order_by else None,
                first=first,
                after=after,
                last=last,
                before=before,
                limit=limit,
                offset=offset,
            )
        )
        nodes = [AutoGeneratedFileRevisionGQL.from_pydantic(item) for item in payload.items]
        edges = [
            AutoGeneratedFileRevisionEdgeGQL(node=node, cursor=encode_cursor(str(node.id)))
            for node in nodes
        ]
        return AutoGeneratedFileRevisionConnectionGQL(
            edges=edges,
            page_info=PageInfo(
                has_next_page=payload.has_next_page,
                has_previous_page=payload.has_previous_page,
                start_cursor=edges[0].cursor if edges else None,
                end_cursor=edges[-1].cursor if edges else None,
            ),
            count=payload.total_count,
        )

    @classmethod
    @override
    async def resolve_nodes(
        cls,
        *,
        info: Info[StrawberryGQLContext, Any],
        node_ids: Iterable[str],
        required: bool = False,
    ) -> Iterable[Self]:
        results = await info.context.data_loaders.auto_generated_file_loader.load_many([
            AutoGeneratedFileID(UUID(node_id)) for node_id in node_ids
        ])
        return cast(list[Self], results)


